import math
def rot(n,cx,cy,r,fn):
    return ''.join(fn(cx+r*math.cos(2*math.pi*i/n-math.pi/2),cy+r*math.sin(2*math.pi*i/n-math.pi/2),360*i/n) for i in range(n))
