    if mi==7: return S(f'<circle cx="50" cy="50" r="20" fill="{g}"/><circle cx="50" cy="50" r="12" fill="{a}"/>'+''.join(f'<line x1="{50+30*math.cos(t):.1f}" y1="{50+30*math.sin(t):.1f}" x2="{50+44*math.cos(t):.1f}" y2="{50+44*math.sin(t):.1f}" stroke="{g}" stroke-width="5" stroke-linecap="round"/>' for t in [2*math.pi*i/12 for i in range(12)]))
