    if mi==9: return S(f'<path d="M50 4C58 24 80 36 80 62C80 80 67 94 50 94C33 94 20 80 20 62C20 46 29 40 33 28C38 40 43 42 45 40C47 28 45 16 50 4Z" fill="{a}"/><path d="M50 40C56 54 66 58 66 72C66 83 59 90 50 90C41 90 34 83 34 72C34 62 44 58 50 40Z" fill="{g}"/>')
    if mi==10: return S(f'<circle cx="50" cy="58" r="32" fill="{a}"/><path d="M36 30L40 14L50 24L60 14L64 30Z" fill="{a}" stroke="{g}" stroke-width="3" stroke-linejoin="round"/><path d="M50 30V88M30 40Q50 62 30 82M70 40Q50 62 70 82" stroke="{g}" stroke-width="3" fill="none" opacity=".7"/>')
